BEGIN
  IF (SELECT count(*) FROM awards) <> 25324 THEN RAISE EXCEPTION 'awards before'; END IF;
  IF (SELECT count(*) FROM awards WHERE source_id='michelin' AND year=2025 AND source_url IS NULL) <> 3212 THEN RAISE EXCEPTION 'no URL before'; END IF;
  SELECT count(*), max(id) INTO led_n, led_max FROM source_capture_ledger; IF led_n <> 194 OR led_max <> 248 THEN RAISE EXCEPTION 'ledger before % / %', led_n, led_max; END IF;
  SELECT count(*), max(id) INTO aud_n, aud_max FROM audit_log; IF aud_n <> 119848 OR aud_max <> 125677 THEN RAISE EXCEPTION 'audit before % / %', aud_n, aud_max; END IF;
  SELECT md5(string_agg(t.id||'|'||t.vid||'|'||t.cat||'|'||t.url, E'\n' ORDER BY t.id)), count(*) INTO s, x FROM (SELECT (e->>0)::bigint AS id, e->>1 AS vid, e->>2 AS cat, e->>3 AS url FROM jsonb_array_elements(p) e) t;
  IF s <> '260aeb2199cf3a4a2b79540f27bc6d95' OR x <> 177 THEN RAISE EXCEPTION 'plan fingerprint % / %', s, x; END IF;
  SELECT count(*) INTO x FROM awards a JOIN (SELECT (e->>0)::bigint AS id, e->>1 AS vid, e->>2 AS cat, e->>3 AS url FROM jsonb_array_elements(p) e) t ON a.id=t.id AND a.venue_id=t.vid AND a.category=t.cat AND a.source_id='michelin' AND a.year=2025 AND a.source_url IS NULL AND a.rank IS NULL AND a.distinction IS NULL;
  IF x <> 177 THEN RAISE EXCEPTION 'rows that match the plan %', x; END IF;

  UPDATE awards a SET source_url=t.url FROM (SELECT (e->>0)::bigint AS id, e->>1 AS vid, e->>2 AS cat, e->>3 AS url FROM jsonb_array_elements(p) e) t WHERE a.id=t.id AND a.venue_id=t.vid AND a.category=t.cat AND a.source_id='michelin' AND a.year=2025 AND a.source_url IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 177 THEN RAISE EXCEPTION 'updated %', n; END IF;
  INSERT INTO source_capture_ledger (publisher, field_type, items, job) VALUES ('michelin','award',177,'url:michelin-2025-switzerland-cards | Swiss open item 4: source_url on 177 legacy Michelin 2025 rows (CH and LI) from web.archive.org captures of the venue cards | window Oct 20 2025 (ceremony) to Oct 22 2026 (before the 2026 Bib list) | meta of each capture names the 2025 guide and the row category | relay docs/open-items-ch-2026-11-03-build/relay-ch-2025-cards-archive.txt sha256 8eac4effc37fd616586b9953821f7b351ab2a7674ce2a4ef3ed74efed253e2ec | no capture for 48 rows, gap stays');

  IF (SELECT count(*) FROM awards) <> 25324 THEN RAISE EXCEPTION 'awards after'; END IF;
  IF (SELECT count(*) FROM awards WHERE source_id='michelin' AND year=2025 AND source_url IS NULL) <> 3035 THEN RAISE EXCEPTION 'no URL after'; END IF;
  IF (SELECT count(*) FROM source_capture_ledger) <> 195 THEN RAISE EXCEPTION 'ledger after'; END IF;
  SELECT count(*) INTO x FROM audit_log WHERE id>aud_max; IF x <> 177 THEN RAISE EXCEPTION 'audit %', x; END IF;
  SELECT count(*) INTO x FROM audit_log WHERE id>aud_max AND table_name='awards' AND action='UPDATE' AND old_row->>'source_url' IS NULL AND new_row->>'source_url' LIKE 'https://web.archive.org/web/%id_/https://guide.michelin.com/%' AND (old_row-'source_url')=(new_row-'source_url');
  IF x <> 177 THEN RAISE EXCEPTION 'audit only source_url %', x; END IF;
END
